TLM.f("Tempora/Pasc7-6",{"officium":"Sabbato Quattuor Temporum Pentecostes","rule":["no Gloria","celebranda aut forma longior aut forma brevior","LectioL5","Sequentia","Credo","Prefatio=Spiritu=hodierna die;"],"ruleInherited":["Gloria","Sequentia","Credo","Prefatio=Spiritu=hodierna die;"],"fallback":"Tempora/Pasc7-0","sections":{"Introitus":[{"k":"ref","la":"Rom 5:5"},{"k":"text","la":"Cáritas Dei diffúsa est in córdibus nostris, allelúja: per inhabitántem Spíritum ejus in nobis, allelúja, allelúja."},{"k":"ref","la":"Ps 102:1"},{"k":"text","la":"Benedic, anima mea, Dómino: et ómnia, quæ intra me sunt, nómini sancto ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Cáritas Dei diffúsa est in córdibus nostris, allelúja: per inhabitántem Spíritum ejus in nobis, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Méntibus nostris, quǽsumus, Dómine, Spíritum Sanctum benígnus infúnde: cujus et sapiéntia cónditi sumus, et providéntia gubernámur."},{"k":"macro","name":"Per Dominum eiusdem"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános"},{"k":"ref","la":"Rom 5:1-5"},{"k":"text","la":"Fratres: Justificáti ex fide, pacem habeámus ad Deum per Dóminum nostrum Jesum Christum: per quem et habémus accéssum per fidem in grátiam istam, in qua stamus, et gloriámur in spe glóriæ filiórum Dei. Non solum autem, sed et gloriámur in tribulatiónibus: scientes, quod tribulátio patiéntiam operátur, patiéntia autem probatiónem, probátio vero spem, spes autem non confúndit: quia cáritas Dei diffúsa est in córdibus nostris per Spíritum Sanctum, qui datus est nobis."}],"Graduale":[{"k":"ref","la":"Ps 116:1-2"},{"k":"text","la":"Laudáte Dóminum, omnes gentes: et collaudáte eum, omnes pópuli."},{"k":"text","la":"Quóniam confirmáta est super nos misericórdia ejus: et véritas Dómini manet in ætérnum.","mark":"V"}],"Sequentia":[{"k":"text","la":"Veni, Sancte Spíritus,"},{"k":"text","la":"et emítte cǽlitus"},{"k":"text","la":"lucis tuæ rádium."},{"k":"sep"},{"k":"text","la":"Veni, pater páuperum;"},{"k":"text","la":"veni, dator múnerum;"},{"k":"text","la":"veni, lumen córdium."},{"k":"sep"},{"k":"text","la":"Consolátor óptime,"},{"k":"text","la":"dulcis hospes ánimæ,"},{"k":"text","la":"dulce refrigérium."},{"k":"sep"},{"k":"text","la":"In labóre réquies,"},{"k":"text","la":"in æstu tempéries,"},{"k":"text","la":"in fletu solácium."},{"k":"sep"},{"k":"text","la":"O lux beatíssima,"},{"k":"text","la":"reple cordis íntima"},{"k":"text","la":"tuórum fidélium."},{"k":"sep"},{"k":"text","la":"Sine tuo númine"},{"k":"text","la":"nihil est in hómine,"},{"k":"text","la":"nihil est innóxium."},{"k":"sep"},{"k":"text","la":"Lava quod est sórdidum,"},{"k":"text","la":"riga quod est áridum,"},{"k":"text","la":"sana quod est sáucium."},{"k":"sep"},{"k":"text","la":"Flecte quod est rígidum,"},{"k":"text","la":"fove quod est frígidum,"},{"k":"text","la":"rege quod est dévium."},{"k":"sep"},{"k":"text","la":"Da tuis fidélibus,"},{"k":"text","la":"in te confidéntibus,"},{"k":"text","la":"sacrum septenárium."},{"k":"sep"},{"k":"text","la":"Da virtútis méritum,"},{"k":"text","la":"da salútis éxitum,"},{"k":"text","la":"da perénne gáudium."},{"k":"text","la":"Amen."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 4:38-44"},{"k":"text","la":"In illo témpore: Surgens Jesus de synagóga, introívit in domum Simónis. Socrus autem Simónis tenebátur magnis fébribus: et rogavérunt illum pro ea. Et stans super illam, imperávit febri: et dimísit illam. Et contínuo surgens, ministrábat illis. Cum autem sol occidísset, omnes qui habébant infírmos váriis languóribus, ducébant illos ad eum. At ille síngulis manus impónens, curábat eos. Exíbant autem dæmónia a multis clamántia et dicéntia: Quia tu es Fílius Dei: et íncrepans non sinébat ea loqui, quia sciébant ipsum esse Christum. Facta autem die egréssus ibat in desértum locum, et turbæ requirébant eum, et venérunt usque ad ipsum: et detinébant illum, ne discéderet ab eis. Quibus ille ait: Quia et áliis civitátibus opórtet me evangelizáre regnum Dei: quia ídeo missus sum. Et erat prǽdicans in synagógis Galilǽæ."}],"Offertorium":[{"k":"ref","la":"Ps 87:2-3"},{"k":"text","la":"Dómine, Deus salútis meæ, in die clamávi et nocte coram te: intret orátio mea in conspéctu tuo, Dómine, allelúja."}],"Secreta":[{"k":"text","la":"Ut accépta tibi sint, Dómine, nostra jejúnia: præsta nobis, quǽsumus; hujus múnere sacraménti purificátum tibi pectus offérre."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joannes 3:8"},{"k":"text","la":"Spíritus, ubi vult, spirat: et vocem ejus audis, allelúja, allelúja: sed nescis, unde véniat aut quo vadat, allelúja, allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Prǽbeant nobis, Dómine, divínum tua sancta fervórem: quo eórum páriter et actu delectémur et fructu."},{"k":"macro","name":"Per Dominum"}],"LectioL1":[{"k":"text","la":"Léctio Joélis Prophétæ"},{"k":"ref","la":"Joel 2:28-32"},{"k":"text","la":"Hæc dicit Dóminus Deus: Effúndam Spíritum meum super omnem carnem: et prophetábunt fílii vestri et fíliæ vestræ: senes vestri sómnia somniábunt, et júvenes vestri visiónes vidébunt. Sed et super servos meos et ancíllas in diébus illis effúndam Spíritum meum. Et dabo prodígia in cœlo et in terra, sánguinem et ignem et vapórem fumi. Sol convertétur in ténebras et luna in sánguinem: ántequam véniat dies Dómini magnus ei horríbilis. Et erit: omnis, qui invocáverit nomen Dómini, salvus erit."},{"k":"macro","name":"Deo gratias"}],"GradualeL1":[{"k":"text","la":"Allelúja."},{"k":"ref","la":"Joannes 6:64"},{"k":"text","la":"Spíritus est, qui vivíficat: caro autem non prodest quidquam."}],"OratioL1":[{"k":"text","la":"Illo nos igne, quǽsumus, Dómine, Spíritus Sanctus inflámmet: quem Dóminus noster Jesus Christus misit in terram, et vóluit veheménter accéndi:"},{"k":"macro","name":"Qui tecum eiusdem"}],"LectioL2":[{"k":"text","la":"Léctio libri Levítici"},{"k":"ref","la":"Lev 23:9-11; 23:15-17; 23:21"},{"k":"text","la":"In diébus illis: Locútus est Dóminus ad Móysen, dicens: Lóquere fíliis Israël, et dices ad eos: Cum ingréssi fuéritis terram, quam ego dabo vobis, et messuéritis ségetem, ferétis manípulos spicárum, primítias messis vestræ ad sacerdótem: qui elevábit fascículum coram Dómino, ut acceptábile sit pro vobis, áltero die sábbati, et sanctificábit illum. Numerábitis ergo ab áltero die sábbati, in quo obtulístis manípulum primitiárum, septem hebdómadas plenas, usque ad álteram diem expletiónis hebdómadæ séptimæ, id est, quinquagínta dies: et sic offerétis sacrifícium novum Dómino ex ómnibus habitáculis vestris, panes primitiárum duos de duábus décimis símilæ fermentátæ, quos coquétis in primítias Dómini. Et vocábitis hunc diem celebérrimum atque sanctíssimum: omne opus servíle non faciétis in eo. Legítimum sempitérnum erit in cunctis habitáculis et generatiónibus vestris: dicit Dóminus omnípotens."},{"k":"macro","name":"Deo gratias"}],"GradualeL2":[{"k":"text","la":"Allelúja."},{"k":"ref","la":"Job 26:13"},{"k":"text","la":"Spíritus ejus ornávit cœlos."}],"OratioL2":[{"k":"text","la":"Deus, qui, ad animárum medélam, jejúnii devotióne castigári córpora præcepísti: concéde nobis propítius; et mente et córpore tibi semper esse devótos."},{"k":"macro","name":"Per Dominum"}],"LectioL3":[{"k":"text","la":"Léctio libri Deuteronómii"},{"k":"ref","la":"Deut 26:1-3; 7-11"},{"k":"text","la":"In diébus illis: Dixit Moyses fíliis Israël: Audi, Israël, quæ ego præcípio tibi hódie. Cum intráveris terram, quam Dóminus, Deus tuus, tibi datúrus est possidéndam, et obtinúeris eam atque habitáveris in ea: tolles de cunctis frúgibus tuis primítias, et pones in cartállo, pergésque ad locum, quem Dóminus, Deus tuus, elégerit, ut ibi invocétur nomen ejus: accedésque ad sacerdótem, qui fúerit in diébus illis, et dices ad eum: Profíteor hódie coram Dómino, Deo tuo, qui exaudívit nos, et respexit humilitátem nostram et labórem atque angústiam: et edúxit nos de Ægýpto in manu forti et bráchio exténto, in ingénti pavóre, in signis atque porténtis: et introdúxit ad locum istum, et trádidit nobis terram lacte et melle manántem. Et idcírco nunc óffero primítias frugum terræ, quam Dóminus dedit mihi. Et dimíttes eas in conspéctu Dómini, Dei tui, et adoráto Dómino, Deo tuo. Et epuláberis in ómnibus bonis, quæ Dóminus, Deus tuus, déderit tibi."},{"k":"macro","name":"Deo gratias"}],"GradualeL3":[{"k":"text","la":"Allelúja."},{"k":"ref","la":"Acts 2:1"},{"k":"text","la":"Cum compleréntur dies Pentecóstes, erant omnes páriter sedéntes."}],"OratioL3":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, salutáribus jejúniis erudíti, ab ómnibus étiam vítiis abstinéntes, propitiatiónem tuam facílius impetrémus."},{"k":"macro","name":"Per Dominum"}],"LectioL4":[{"k":"text","la":"Léctio libri Levítici"},{"k":"ref","la":"Lev 26:3-12"},{"k":"text","la":"In diébus illis: Dixit Dóminus ad Móysen: Lóquere fíliis Israël, et dices ad eos: Si in præcéptis meis ambulavéritis, et mandáta mea custodiéritis et fecéritis ea, dabo vobis plúvias tempóribus suis, et terra gignet germen suum, et pomis árbores replebúntur. Apprehéndet méssium tritúra vindémiam, et vindémia occupábit seméntem: et comedétis panem vestrum in saturitáte, et absque pavóre habitábitis in terra vestra. Dabo pacem in fínibus vestris: dormiétis, et non erit, qui extérreat. Auferam malas béstias, et gládius non transíbit términos vestros. Persequémini inimícos vestros, et córruent coram vobis. Persequéntur quinque de vestris centum aliénos et centum de vobis decem mília: cadent inimíci vestri gládio in conspéctu vestro. Respíciam vos et créscere fáciam: multiplicabímini, et firmábo pactum meum vobíscum. Comedétis vetustíssima véterum, et vétera novis superveniéntibus projiciétis. Ponam tabernáculum meum in médio vestri, et non abjíciet vos ánima mea. Ambulábo inter vos, et ero Deus vester, vosque éritis pópulus meus: dicit Dóminus omnípotens."},{"k":"macro","name":"Deo gratias"}],"GradualeL4":[{"k":"text","la":"Allelúja."},{"k":"text","la":"(Hic genuflectitur) Veni, Sancte Spíritus, reple tuórum corda fidélium: et tui amóris in eis ignem accénde.","mark":"V"}],"OratioL4":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: sic nos ab épulis carnálibus abstinére; ut a vítiis irruéntibus páriter jejunémus."},{"k":"macro","name":"Per Dominum"}],"LectioL5":[{"k":"text","la":"Léctio Daniélis Prophétæ"},{"k":"ref","la":"Dan 3:47-51"},{"k":"text","la":"In diébus illis: Angelus Dómini descéndit cum Azaría et sóciis ejus in fornácem: et excússit flammam ignis de fornáce, et fecit médium fornácis quasi ventum roris flantem. Flamma autem effundebátur super fornácem cúbitis quadragínta novem: et erúpit, et incéndit, quos répperit juxta fornácem de Chaldǽis, minístros regis, qui eam incendébant. Et non tétigit eos omníno ignis, neque contristávit, nec quidquam moléstiæ íntulit. Tunc hi tres quasi ex uno ore laudábant, et glorificábant, et benedicébant Deum in fornáce, dicéntes:"},{"k":"macro","name":"Deo gratias"}],"GradualeL5":[{"k":"text","la":"Allelúja."},{"k":"ref","la":"Dan 3:52"},{"k":"text","la":"Benedíctus es, Dómine, Deus patrum nostrórum, et laudábilis in sǽcula."}],"OratioL5":[{"k":"text","la":"Deus, qui tribus púeris mitigásti flammas ígnium: concéde propítius; ut nos fámulos tuos non exúrat flamma vitiórum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"de9115ac5ff1dcde":{"t":"Rim 5, 5, Ps 102, 1\n(Rim 5, 5) Ljubav se Božja izlila u našim srcima, <i>aleluja</i>,\npo Duhu Svetom, koji stanuje u nama, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 102, 1) Blagoslivljaj, dušo moja, Gospodina! I sve što je u meni sveto ime njegovo.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Rim 5, 5) Ljubav se Božja izlila u našim srcima, <i>aleluja</i>,\npo Duhu Svetom, koji stanuje u nama, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Rim. 5, 5). Ljubav se Božja izlila u srcima našim., aleluja, po Duhu Svetom, koji nam je dan aleluja, aleluja: (Ps. 102, 1). Blagosivaj, dušo moja' Gospodina, i sve, što je u meni, sveto ime njegovo’. Slava Ocu . . . Ljubav . . . se« dijeli se prva tonzura,.. a onda se«, bez »Prignimo . , a tako i, <i>aleluja</i>, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 354–355 (snimka 178) (OCR)"},"7cf4a1d546ca4072":{"t":"<i>Pomolimo se</i>.\nUlij, molimo, Gospodine, dobrostivo Duha Svetoga u naše duše da nas njegov promisao upravlja kao što nas je njegova mudrost stvorila.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Ulij, molimo., Gospodine, blagoslov Duha Svetoga u naše duše, da nas njegov promisao upravlja, kao. što nas je njegova mudrost stvorila, po G. n. . . . u jedinstvu istoga Duha . . .","knRef":"Kniewald 1942, str. 354–355 (snimka 178) (OCR)"},"477c51a71e0cd16d":{"t":"Jl 2, 28-32\nČitanje Joela proroka. Ovo govori Gospodin Bog: Izlit ću Duh svoj na svako tijelo i prorokovat će vaši sinovi i vaše kćeri. Starci će vaši usnuti sne i mladići će vaši vidjeti viđenja. U one ću dane izliti Duh svoj na svoje sluge i službenice. I dat ću znakove na nebu i na zemlji, krv i plamen i dim, što se puši. Sunce će se pretvoriti u tamu i mjesec u krv prije nego dođe dan Gospodnji veliki i strašni. I zbit će se: svaki koji zazove ime Gospodnje, spasit će se.","kn":"Čitanje Joela proroka (2, 28-32), Ovo govori Gospodin Bog: Izlit ću Duh svoj na svako tijelo i prorokovat će sinovi vaši i kćeri vaše; starci će vaši usni'ti sne i mladići će vaši vidjeti viđenja. U one ću dane izliti Duh svoj na sluge i službenice svoje I dat ću znakove na nebu i na zemlji, krv i plamen i dim, što se puši. Sunce će se pretvoriti u tamu i mjesec u krv, prije nego dođe dan Gospodnji, veliki i strašni. I zbit će se: svaki, koji zazove ime Gospodnje, spasit će se.","knRef":"Kniewald 1942, str. 354–355 (snimka 178) (OCR)"},"63a2ac83d5f594c1":{"t":"Iv 6, 64\n<i>Aleluja</i>.\nDuh je onaj koji oživljuje a tijelo ne koristi ništa."},"b3e88b31e3d876f2":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, raspalio nas Duh Sveti onim ognjem, koji je Gospodin naš Isus Krist poslao na zemlju želeći da se jako ražeže.\n<i>Koji s Tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, raspalio nas Duh Sveti o.nim ognjem, koji je Gospodin naš, Isus Krist, poslao na, zemlju želeći da se veoma užge, koji s Tobom ... u jedinstvu istoga Duha . . .","knRef":"Kniewald 1942, str. 354–355 (snimka 178) (OCR)"},"0b50b54c474af8d0":{"t":"Lev 23, 9-11, 15-17 i 21\nČitanje Knjige levitske. U one dane reče Gospodin Mojsiju :Kaži sinovima Izraelovim: Kad uđete u zemlju koju ću vam dati, svaki put kad saberete žetvu, donesite svećeniku prvine vaše žetve, snopove klasja. On neka podigne pred Gospodinom i posveti mu svežanj klasja u prvi dan iza subote, da po njemu budete prijatni Gospodinu. Onda brojite od toga dana iza subote, kad ste prinijeli snop prvina, sedam punih sedmica sve do dana iza završetka sedme sedmice, to jest do pedesetog dana. Tada ćete prinijeti Gospodinu novu žrtvu iz svih stanova svojih: dva kruha prvenca koji su ispečeni od dvije desetine bijeloga brašna kao prvine za Gospodina. To neka vam bude vrlo svečan i presveti dan. Toga dana ne radite nikakva teškog posla. To neka bude vječni zakon u svim stanovima i pokoljenjima vašim, govori Gospodin svemogući.","kn":"Čitanje knjige Levitika (23, 9-21). U one dane reče Go.spodiii M'Ojsiju govoreći: Reci sinovima Izrealovim i kaži im: Ka.d uniđete u zemlju, koju ću vam dati, i kad saberete žetvu, donijet ćete snopoveprvence svećeniku, koji će ih podići pred Gospodinom u dan iza subote i posvetit će ih, da po njima budete prijatni Gospodinu. Onda brojite od dana iza subote, kad ste prinijeli snopove-prvence, sedam punih sedmica, do dana, .kad se navrši sedma sedmica, to jest pedeset dana. Tada ćete Gospodinu iz svih stanova svojih prinijeti novu žrtvu, dva bljeba-prvenca od dvije desetine čistoga finoga brašna, koje ste spekli kao prvence Goapodinu. ' I prozvat ćete ovaj dan svečanim i svetim, i tog dana ne ćete raditi težačkog /posla. To neka vrijedi kao vječni zakon u svim sta, novima i pokoljenjima vašim, veli Gospodin svemogući.","knRef":"Kniewald 1942, str. 354–355 (snimka 178) (OCR)"},"ceb1211278e13ecf":{"t":"Job 26, 13\n<i>Aleluja</i>.\nDuh je njegov ukrasio nebesa."},"a9b97a51e56cd529":{"t":"<i>Pomolimo se</i>.\nBože, koji si za lijek duša odredio da tjelesa poste, udijeli nam milostivo da ti budemo odani i dušom i tijelom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si zapovjedio, da se tijelo trapi pobožnim postom na okrepu duše, dopusti nam milostivo, da Ti uvijek služimo 1 tijelom i dušom, po G. n.","knRef":"Kniewald 1942, str. 356–357 (snimka 179) (OCR)"},"4fd111826d6d80cf":{"t":"Pnz 26, 1-11\nČitanje knjige Ponovljenog Zakona. U one dane reče Mojsije sinovima Izraelovim: Čuj, Izraele, što ti ja danas zapovijedam! Kad uđeš u zemlju koju će ti Gospodin Bog tvoj dati u posjed, kad je zauzmeš i nastaniš se u njoj, uzmi prvine od svih plodova što ih ubereš i stavi ih u košaru i pođi do mjesta koje će izabrati Gospodin Bog tvoj da se tamo zazivlje ime njegovo. Pristupi k svećeniku, koji bude tu u ono vrijeme, i reci mu: Priznajem danas pred Gospodinom Bogom tvojim koji nas je uslišio i pogledao na naše poniženje, muke i nevolje i jakom nas rukom izveo iz Egipta u silnom strahu, znakovima i čudesima, te nas doveo na ovo mjesto i predao nam zemlju u kojoj teče mlijeko i med. Radi toga evo prinosim prvine plodova zemlje koju mi je dao Gospodin. I ostavi ih pred Gospodinom Bogom svojim pošto si se poklonio Gospodinu Bogu svome. I blaguj od svih dobara koje će ti dati Gospodin Bog tvoj.","kn":"Čitanje knjige Deuteronomija (26, 1-11). U one dane reče Mojsije sinovima Izraelskim: Cuj, Izraele, što ti ja danas određujem: Kad uniđeš u zemlju, koju će ti dati Gospodin Bog da je posjeduješ, i kad je zaposjedneš, i kad je budeš nastanio: uzet ćeš od svih plodova, što ih ubereš, prvence, i stavit ćeš ih u košaru i poći ćeš do mjesta, koje će izabrati Gospodin Bog tvoj, da se tamo zaziva ime njegovo. I pristupit ćeš k svećeniku, koji bude ondje u ono vrijeme, i reći ćeš mu: Ispovijedam danas pred Gospodinom Bogom tvojim, koji nas je usUšap i koji je pogledao na poniženje naše, na muke i tjeskobe naše, te nas jakom rukom izveo iz Egipta u silnom strahu, znakovima I čudesima, i uveo nas u ovu zemlju i predao nam zemlju, koja teče medom i mlijekom. Toga radi prinosim sada prvtnce plodova zemlje, koju mi je Gospodin dao. I ostavit ćeš ih pred licem Gospo^dlna Boga tvoga i poklonit ćeš ,se Gospodinu Bogu tvomu. I jesti ćeš onda sve ono dobro, što ti Gospodin Bog tvoj dade.","knRef":"Kniewald 1942, str. 356–357 (snimka 179) (OCR)"},"8b02759d0a12ba4f":{"t":"Act 2, 1\n<i>Aleluja</i>.\nKad su se navršili dani Pedesetnice, svi su zajedno sjedili."},"04240ee0f866246c":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, svemogući Bože, da nas spasonosni post potakne da se ostavimo mana i tako lakše isprosimo tvoje smilovanje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, da poučeni spasonosnim postom i uzdržavajući se od svih opačina, lakše postignemo Tvoje oproštenje, po Gosip. n.","knRef":"Kniewald 1942, str. 356–357 (snimka 179) (OCR)"},"b23e31fdb3d12168":{"t":"Lev 26, 3-12\nČitanje Knjige levitske. U one dane reče Gospodin Mojsiju: Kaži sinovima Izraelovim: Budete li išli putem mojih zapovijedi i vršili moje odredbe, davat ću vam kišu u pravo vrijeme i zemlja će donositi rod svoj a stabla će biti puna voća. Žetva se neće moći dovršiti prije berbe, a berba prije sjetve. Imat ćete obilno kruha i živjet ćete bez straha u svojoj zemlji. Dat ću mir zemlji vašoj. Spavat ćete spokojno i neće biti nekoga tko bi vas uznemirivao. Istrijebit ću divlje zvijeri i mač neće prijeći granica vaših. Progonit ćete svoje neprijatelje i padat će pred vama. Petorica vaših će progoniti stotinu tuđinaca a stotina vaših deset tisuća. Pogledat ću na vas i umnožit ću vas. Postat ćete mnogobrojni i učvrstit ću savez svoj s vama. Hranit ćete se plodovima iz prošlih godina, a staro ćete baciti, jer će pridolaziti novo. Postavit ću šator svoj među vama i neće vas odbiti srce moje. Prebivat ću među vama i biti Bog vaš, a vi ćete biti moj narod, govori Gospodin svemogući.","kn":"Čitanje knjige Levitika (26, 3-12). U one dane reče Gospodin Mojsiju: Govori sinovima Izraelovim i reci im: Budete li išli putem zapovijedi mojih^ i budete li obdržavali odredbe moje, dat ću vam kišu u određeno vrijeme i zemlja će donijeti plod svoj i drveće će se napuniti voćem. Žetva će doseći berbu i berba će dostići sjetvu. Jest ćete kruh svoj nasićeni i nastavat ćete zemlju svoju bez straha. Dat ću mir u zemlji vašoj, spavat ćete i ne će biti onoga, koji bi vas plašio. Istrijebit ću divlje zvijeri i mač ne će prijeći granica vaših. Progonit ćete neprijatelje svoje i padat će pred vama. Progonit će petorica vaših stotinu stranih i stotina vaših deset tisuća; neprijatelji će vaši pasti pod mačem pred licem vašim. Pogledat ću na vas i učinit ću vas brojnima,, umnožit ćete se i učvrstit ću zavjet svoj s vama. Jest ćete plodove iz prošlih godina i stare ćete plodine baciti, jer će pridoći novi. Postavit ću šator svoj u vašu sredinu i ne ću vas zabaciti. Bit ću među vama i bit ću Bog vaš, a vi ćete biti puk moj: veli Gospodin svemogući.","knRef":"Kniewald 1942, str. 356–357 (snimka 179) (OCR)"},"524a29874efa37ce":{"t":"<i>Aleluja</i>.\n[Ovdje se poklekne] Dođi, Duše Sveti, napuni srca svih vjernih i zapali u njima oganj svoje ljubavi.","kn":"<i>Aleluja</i>.\n. (Ovdje se poklekne.) .Dođi Duše Sveti i napuni srca svojih vjernih i zapali u njima oganj ljubavi svoje.","knRef":"Kniewald 1942, str. 350–351 (snimka 176) (OCR)"},"806ad6a671acb850":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da nam uzdržavanje od tjelesne hrane bude poticaj da se uzdržavamo i od mana koje nas obuzimaju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, da se tako uzdržajemo od tjelesnih gozbi, te se odvratimo i od opačina, koje na nas navaljuju, po G. n.","knRef":"Kniewald 1942, str. 358–359 (snimka 180) (OCR)"},"f3b9abeff48a1c81":{"t":"Dn 3, 47-51\nČitanje Danijela proroka. U one dane siđe anđeo Gospodnji s Azarijom i njegovim drugovima u užarenu peć. Istjerao je plamen iz peći te je usred peći bilo hladno kao da puše vjetar. A plamen se nad peć dizao četrdesetdevet lakata, izbijao je iz peći i sažegao koga je god zahvatio od Kaldejaca, kraljevih službenika. A njih se oganj nije dotakao niti ih je opario, niti ih je najmanje ozlijedio. Tada su u užarenoj peći jednoglasno zapjevali pjesmu slave i veličali Boga govoreći [Ovdje se ne odgovori Deo gratias]:","kn":"Čitanje Danijela proroka (3, 47-51). U one je dane sašao anđeo Gospodnji s Azarijom i drugovima njegovim u užarenu peć; on je tj'erao plamen iz peči i učinio je, da je usred peći bilo hladno, kao da puše vjetar. A plamen se izdizao nad peći četrdesetidevet lakata i izbio je iz peći i zapalio svakoga, koga je zahvatio od Kaldejaca, službenika kraljevih. Ali njih same nije dotakao plamen ni najmanje, niti ih oštetio ili ozlijedio. Tada zapjevaše kao jednoglasno pjesmu slave i stavljahu Bogai, u užarenoj peći govoreći: . i i i , I","knRef":"Kniewald 1942, str. 48–49 (snimka 25) (OCR)"},"06c1572e0dc8ddd5":{"t":"Dan 3, 52\n<i>Aleluja</i>.\nBlagoslovljen si, Gospodine, Bože otaca naših. I dostojan hvale i slavan u vijeke.","kn":"<i>Aleluja</i>.\n.Blagosloven si, Gospodine, Bože otaca naših, i pun slave u vjekove.","knRef":"Kniewald 1942, str. 360–361 (snimka 181) (OCR)"},"6073d3b7d83d95a7":{"t":"<i>Pomolimo se</i>.\nBože, koji si trojici mladića ublažio žestinu vatre, dopusti milostivo da nas sluge tvoje ne sažeže plamen opačina.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si trojici mladića ublažio žar ognjen, dopusti umllostivljen, da nas, sluge Tvoje, ne sažge plamen opačina, i>o G. n. I. K.","knRef":"Kniewald 1942, str. 50–51 (snimka 26) (OCR)"},"263b53a37262dc4e":{"t":"Rim 5, 1-5\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo! opravdani vjerom imamo mir s Bogom po Gospodinu našemu Isusu Kristu, po kome smo vjerom pristupili k ovoj milosti, u kojoj stojimo i ponosimo se nadom u slavu djece Božje. Ne samo to, nego se ponosimo i nevoljama znajući da nevolja gradi ustrajnost, a ustrajnost prokušanu vrlinu, a prokušana vrlina nadu, a nada ne sramoti, jer se ljubav Božja izlila u srcima našim po Duhu Svetom koji nam je dan.","kn":"Čitanje poslanice bi. Pavla apostola Rimljanima (5, 1-5). Braćo! opravdani vjerom, imamo mir s Bogom po Gospodinu našemu Isusu Kristu, po kom smo vjerom ipristupili k ovoj milosti; u kojoj stojimo i ponosimo se nadom u slavu djece Božje. Ne samo to, nego se ponosimo i nevoljama znajući, da nevolja gradi ustrajnost, a ustrajnost prokušanu vrlinu, a prokušana vrlina nadu, a nada ne sramoti, jer se ljubav Božja izlila u srcima našima Duhom svetim, koji nam je dan.","knRef":"Kniewald 1942, str. 358–359 (snimka 180) (OCR)"},"5f107e4031aa705c":{"t":"Ps 116, 1-2\nHvalite Gospodina, sva plemena, hvalite ga, svi narodi. Jer je silno nad nama milosrđe njegovo, i istina Gospodnja ostaje dovijeka.","kn":"(Ps. 116, 1, 2). Hvalite Gospodina sva plemena, hvalite ga svi narodi, jer je silno nad nama njegovo milosrđe i istina Gospodnja ostaje dovijeka.","knRef":"Kniewald 1942, str. 340–341 (snimka 171) (OCR)"},"5094c38aeef90284":{"t":"Dođi, duše presveti, /Sa neba nas posjeti /Zrakom svoje milosti. <i>\n</i>\nDođi, Oče ubogih,/Djelitelju dara svih,/Dođi, srca svjetlosti. <i>\n</i>\nTješitelju tako blag, /Ti nebeski Goste drag, /Pun miline hlade tih. <i>\n</i>\nUmornima odmore,/U vrućini lahore,/Razgovore žalosnih. <i>\n</i>\nSjaju svjetla blaženog,/Sjaj u srcu puka svog,/Napuni nam dušu svu. <i>\n</i>\nBez božanstva tvojega /Svi smo mi bez ičega,/Tonemo u crnom zlu. <i>\n</i>\nNečiste nas umivaj,/Suha srca zalivaj, /Vidaj rane ranjenim. <i>\n</i>\nMekšaj ćudi kamene,/ Zagrij grudi ledene,/Ne daj nama putem zlim. <i>\n</i>\nSvim što vjeru imaju,/Što se u te ufaju, /Sedam svojih dara daj. <i>\n</i>\nDaj nam krepost zaslužnu/I smrt lijepu, blaženu,/Daj vjekovit svima raj. <i>\n</i>\n<i>amen</i>, <i>aleluja</i>.","v":"aleluia → ∅"},"d0a6f4a27bb85057":{"t":"Lk 4, 38-44\nSlijedi sveto Evanđelje po Luki. U ono vrijeme ustavši Isus iz zbornice, uđe u kuću Šimunovu. A Šimunovu je punicu uhvatila velika groznica i stanu ga moliti za nju. I stavši više nje zapovjedi groznici i pusti je. I odmah ustade i služaše im. A kad sunce zađe, svi koji su imali bolesnike od različitih bolesti, dovedoše ih k njemu. A on stavljajući ruke na svakoga od njih stane ih iscjeljivati. I đavli su izlazili iz mnogih vičući i govoreći: Ti si Sin Božji! Ali on im je branio i ne dade im govoriti jer su znali da je on Krist. Kad nastade dan, izađe i otiđe u pusto mjesto, i narod ga je tražio i dođe k njemu te su ga ustavljali da ne ide od njih. A on im reče: I drugim gradovima treba mi navijestiti kraljevstvo Božje, jer sam za to poslan. I propovijedao je po zbornicama Galilejskim.","kn":"t Slijedi sv^ evanđelje po Lukl (4, 38-44). U ono vrijeme ustavši Isus iz zbornice, uđe u . kuću Simunovu. A punicu je Šimunovu uhvatila velika groznica, i stanu ga moliti za nju. I stavši više nje zapovjedi groznici, i pusti je. I odmah ustade i sluzase im. A kad sunce zađe, svi, koji su imali bolesnike od različitih bolesti, dovedoše ih k njemu. A on stavljajući ruke na svakoga od njih, stane ih rscjel.iivati. I đavli su izlazili iz mnogih vičući i govoreći. Ti si Sin Božji. Ali on im je branio i ne dade im govoriti, jer su znali, da je on Krist. Kad nastade dan, izađe i otide u pusto mjesto, i narod ga je tražio, i dođe k njemu, te su ga sustavljali da ne ide od njih. A on im reče; I drugim gradovima treba mi navijestiti kraljevstvo Božje; jer sam za to poslan. I propovijedao je po zbornicama Galilejskim.","knRef":"Kniewald 1942, str. 162–163 (snimka 82) (OCR)"},"32ce4d61e4eddb60":{"t":"Ps 87, 2-3\nGospodine, Bože spasenja mojega, danju i noću vapijem pred tobom! Vinula se moja molitva pred tvoje lice, <i>aleluja</i>.","kn":"(Ps. 87, 2, 3). Gospodine Bože, spasitelju moj, danju 1 noću vapijem k Tebi, vinula se molitva moja pred lice Tvoje! <i>Aleluja</i>.","knRef":"Kniewald 1942, str. 128–129 (snimka 65) (OCR)"},"02751ba8a8866c21":{"t":"Da ti budu mili naši postovi, podaj nam,molimo, Gospodine, da ti prinesemo naša srca očišćena darom ovog otajstva.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Da Ti budu prijatni naši postovi, podaj nam, molimo. Gospodine, da Ti prinesemo srca naša očišćena darom ovog otajstva, po G. n.","knRef":"Kniewald 1942, str. 358–359 (snimka 180) (OCR)"},"e36be14714c3ff04":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. On uziđe nad sva nebesa, sjede uz tvoju desnu, te obećanog Duha Svetoga na današnji dan izli na posinjenu djecu. – Stoga sav svijet na krugu zemaljskom kliče zanosnom radošću, a i višnje sile i s njima anđeoske vlasti zajedno pjevaju pjesmu tvoje slave govoreći bez prestanka:","kn":"Predslovlje: Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi. Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospodinu našem, koji je uzašao nad sva nebesa i sjeo s desne Tvoje i na današnji dan izlio obećanoga Duha Svetoga na Božje posinke. Zato kliče čitav svijet i svemir pun veselja. A i višnje moći i anđeoske vlasti pjevaju pjesmu Tvoje slave govoreći bez prestanka:","knRef":"Kniewald 1942, str. 344–345 (snimka 173) (OCR)"},"8a2c2cbb903fdbf4":{"t":"Iv 3, 8\nDuh duše gdje hoće i čuješ njegov glas, <i>aleluja</i>, <i>aleluja</i>,\nali ne znaš otkud dolazi ni kamo ide, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Iv. 3, 8). Duh duše, gdje hoće i čuješ glas njegov, aleluja, aleluja, ali ne znaš otkud dolazi, ni kamo ide, aleluja, aleluja aleluja.","knRef":"Kniewald 1942, str. 358–359 (snimka 180) (OCR)"},"9d873aa39c5de148":{"t":"<i>Pomolimo se</i>.\nNapunila nas, Gospodine, tvoja sveta otajstva božanskim žarom, te uživali i u njihovu vršenju i plodu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Prožele nas, Gospodine, Tvoje svetinje božanskim žarom, te uživamo i u njihovu vršenju i plodu, po G. n.","knRef":"Kniewald 1942, str. 358–359 (snimka 180) (OCR)"},"8986d237bd5894a0":{"t":"Dođi, duše presveti, /Sa neba nas posjeti /Zrakom svoje milosti. <i>\n</i>\nDođi, Oče ubogih,/Djelitelju dara svih,/Dođi, srca svjetlosti. <i>\n</i>\nTješitelju tako blag, /Ti nebeski Goste drag, /Pun miline hlade tih. <i>\n</i>\nUmornima odmore,/U vrućini lahore,/Razgovore žalosnih. <i>\n</i>\nSjaju svjetla blaženog,/Sjaj u srcu puka svog,/Napuni nam dušu svu. <i>\n</i>\nBez božanstva tvojega /Svi smo mi bez ičega,/Tonemo u crnom zlu. <i>\n</i>\nNečiste nas umivaj,/Suha srca zalivaj, /Vidaj rane ranjenim. <i>\n</i>\nMekšaj ćudi kamene,/ Zagrij grudi ledene,/Ne daj nama putem zlim. <i>\n</i>\nSvim što vjeru imaju,/Što se u te ufaju, /Sedam svojih dara daj. <i>\n</i>\nDaj nam krepost zaslužnu/I smrt lijepu, blaženu,/Daj vjekovit svima raj. <i>\n</i>\n<i>amen</i>, <i>aleluja</i>."}},"variants":{"brevior":{"Graduale":[{"k":"text","la":"Allelúja."},{"k":"text","la":"(Hic genuflectitur) Veni, Sancte Spíritus, reple tuórum corda fidélium: et tui amóris in eis ignem accénde.","mark":"V"}],"Sequentia":[{"k":"text","la":"Veni, Sancte Spíritus,"},{"k":"text","la":"et emítte cǽlitus"},{"k":"text","la":"lucis tuæ rádium."},{"k":"sep"},{"k":"text","la":"Veni, pater páuperum;"},{"k":"text","la":"veni, dator múnerum;"},{"k":"text","la":"veni, lumen córdium."},{"k":"sep"},{"k":"text","la":"Consolátor óptime,"},{"k":"text","la":"dulcis hospes ánimæ,"},{"k":"text","la":"dulce refrigérium."},{"k":"sep"},{"k":"text","la":"In labóre réquies,"},{"k":"text","la":"in æstu tempéries,"},{"k":"text","la":"in fletu solácium."},{"k":"sep"},{"k":"text","la":"O lux beatíssima,"},{"k":"text","la":"reple cordis íntima"},{"k":"text","la":"tuórum fidélium."},{"k":"sep"},{"k":"text","la":"Sine tuo númine"},{"k":"text","la":"nihil est in hómine,"},{"k":"text","la":"nihil est innóxium."},{"k":"sep"},{"k":"text","la":"Lava quod est sórdidum,"},{"k":"text","la":"riga quod est áridum,"},{"k":"text","la":"sana quod est sáucium."},{"k":"sep"},{"k":"text","la":"Flecte quod est rígidum,"},{"k":"text","la":"fove quod est frígidum,"},{"k":"text","la":"rege quod est dévium."},{"k":"sep"},{"k":"text","la":"Da tuis fidélibus,"},{"k":"text","la":"in te confidéntibus,"},{"k":"text","la":"sacrum septenárium."},{"k":"sep"},{"k":"text","la":"Da virtútis méritum,"},{"k":"text","la":"da salútis éxitum,"},{"k":"text","la":"da perénne gáudium."},{"k":"text","la":"Amen. Allelúja."}]}}});
